// clang-format on

/// The theme's controls by id; the first theme's for one it doesn't know.
inline const ControlSkin& FindControlSkin(std::string_view id) noexcept
{
    for (const auto& skin : kControlSkins)
    {
        if (skin.id == id)
        {
            return skin;
        }
    }

    return kControlSkins[0];
}
